<?php namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; class AuthController extends Controller { public function register(Request $r){$d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users','password'=>'required|min:8|confirmed']);$u=User::create($d+['role'=>'user','status'=>'active']);return response()->json(['data'=>['user'=>$u,'token'=>$u->createToken('web')->plainTextToken]],201);} public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required']);$u=User::where('email',$d['email'])->first();if(!$u||!Hash::check($d['password'],$u->password)||$u->status!=='active')return response()->json(['message'=>'Invalid credentials'],422);return ['data'=>['user'=>$u,'token'=>$u->createToken('web')->plainTextToken]];} public function me(Request $r){return ['data'=>$r->user()];} public function logout(Request $r){$r->user()->currentAccessToken()->delete();return response()->noContent();} }
